#!/usr/bin/env bash
set -euo pipefail
dir=""; input=""; name=""
usage() { echo "usage: $0 -d DIR [-i INPUT] [-n NAME]" >&2; exit 1; }
while getopts ":d:i:n:" opt; do
  case "$opt" in
    d) dir="$OPTARG" ;;
    i) input="$OPTARG" ;;
    n) name="$OPTARG" ;;
    *) usage ;;
  esac
done
[ -n "${dir}" ] || usage
echo "dir=${dir} input=${input} name=${name}"

#!/usr/bin/env bash
set -euo pipefail
file="${1:-sample.jpg}"
case "$file" in
  *.jpg|*.png|*.gif) echo "image" ;;
  *.tar.gz|*.zip|*.gz) echo "archive" ;;
  *.pdf|*.txt|*.md) echo "document" ;;
  *.csv|*.tsv|*.log) echo "data" ;;
  *.mp4|*.mkv) echo "video" ;;
  *) echo "other" ;;
esac
